package com.wissenup.domain.fee.repository;import com.wissenup.domain.fee.entity.FeePayment;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import java.util.*;public interface FeePaymentRepository extends JpaRepository<FeePayment,Long>{List<FeePayment>findAllByOrganizationIdOrderByPaymentDateDescCreatedAtDesc(Long org);List<FeePayment>findAllByOrganizationIdAndStudentIdOrderByPaymentDateDescCreatedAtDesc(Long org,Long student);Optional<FeePayment>findByPaymentIdAndOrganizationId(Long id,Long org);Optional<FeePayment>findByOrganizationIdAndReceiptNumber(Long org,String receipt);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from FeePayment p where p.paymentId=:id and p.organizationId=:org")Optional<FeePayment>lockByIdAndOrganizationId(Long id,Long org);}
